package main

import (
	"bufio"
	"fmt"
	"os"
)

func readLines(path string) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		fmt.Println(scanner.Text())
	}
	return scanner.Err()
}
```

> **Tip:** Use `bufio.Scanner` for efficient line-by-line reading. It handles memory management automatically.

- **Open** the file using `os.Open`.
- **Defer close** to ensure the file is closed properly.
- **Scan** each line and print it.
- **Check errors** from scanner to catch read issues.

