func ReadFileLineByLine(filename string) ([]string, error) {
    file, err := os.Open(filename)
    if err != nil {
        return nil, err
    }
    defer file.Close()

    var lines []string
    scanner := bufio.NewScanner(file)
    for scanner.Scan() {
        lines = append(lines, scanner.Text())
    }

    if err := scanner.Err(); err != nil {
        return nil, err
    }

    return lines, nil
}
```

**Explanation:**
1. Opens the file using `os.Open`.
2. Uses `bufio.Scanner` to read line by line, which handles line endings automatically.
3. Appends each line to a slice using `scanner.Text()`.
4. Checks for errors during scanning (e.g., I/O issues).
5. Returns the collected lines or any encountered error.

**Note:** For very large files, consider processing lines in a loop instead of storing them all in memory.
